point = Point(3.0, 4.0)
assert point.squared_length() == 25.0
assert scale(3.0) == 6.0
assert scale(3.0, factor=4.0) == 12.0
)");
    } catch(const py::python_error& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
    return 0;
}

